insert into organizations(id,name,slug,owner_email,google_url,brand_color,address,timezone,industry_category,plan_tier,branding_config)
insert into customers(id,org_id,name,email,phone,email_consent,sms_consent,consent_at,consent_source,opted_out_sms,opted_out_email,opted_out_at)
insert into requests(id,org_id,customer_id,channel,token,short_token,status,created_at,clicked_at,sent_at,delivered_at)
insert into messages(org_id,request_id,step,channel,status,due_at,sent_at,delivered_at,error)
insert into reviews(id,org_id,external_review_id,author,rating,body,published_at)
insert into review_stats(org_id,total,average) values('d0000000-0000-4000-8000-000000000001',128,4.7) on conflict(org_id) do nothing;
insert into feedback(id,org_id,request_id,customer_id,body,contact_preference) values('d4000000-0000-4000-8000-000000000001','d0000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001','Could you open earlier on Saturdays?','email') on conflict(id) do nothing;
insert into message_templates(organization_id,name,channel,sequence_step,delay_hours,subject,body) select 'd0000000-0000-4000-8000-000000000001',channel||' step '||step,channel,step,case when step=1 then 0 else 72 end,case when channel='email' then 'How was your visit?' end,'Hi {{customer_name}}, thank you for visiting {{business_name}}. Share your honest experience: {{review_link}}. {{opt_out_text}}' from (values('sms'),('email'))c(channel) cross join (values(1),(2))s(step) on conflict(organization_id,channel,sequence_step) do nothing;
insert into monthly_reports(organization_id,month,metrics) values('d0000000-0000-4000-8000-000000000001',date_trunc('month',now()-interval '1 month')::date,'{"contacted":84,"sent":112,"delivered":108,"clicked":38,"requests":84,"opt_outs":2,"new_reviews":14,"feedback":3}') on conflict(organization_id,month) do nothing;
