-- Fictional demonstration data. No auth account or password is seeded.
-- Link an existing Supabase Auth user using the documented membership insert.
values('d0000000-0000-4000-8000-000000000001','Brooklyn Corner Barbers','brooklyn-corner-demo','demo-owner@example.com','https://search.google.com/local/writereview?placeid=DEMO_NOT_A_REAL_BUSINESS','#5369e8','123 Demo Avenue, Brooklyn, NY','America/New_York','barbershop','premium','{"welcome_headline":"How was your visit?","counter_cta":"Share your honest experience","accent_color":"#e9ba59"}') on conflict(id) do nothing;
select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'d0000000-0000-4000-8000-000000000001',name,'demo-customer-'||n||'@example.com','+1212555010'||n,true,true,now()-interval '7 days','manual_entry',n=5,n=5,case when n=5 then now()-interval '1 day' end
from (values(1,'Alex Rivera'),(2,'Jordan Kim'),(3,'Sam Ortiz'),(4,'Taylor Brown'),(5,'Casey Lee'))s(n,name) on conflict(id) do nothing;
select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'d0000000-0000-4000-8000-000000000001',('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n%2=0 then 'email' else 'sms' end,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=1 then 'demo-visit' end,case when n=1 then 'clicked' when n=4 then 'failed' when n=5 then 'opted_out' else 'delivered' end,now()-interval '2 days',case when n=1 then now()-interval '1 day' end,now()-interval '2 days',case when n<4 then now()-interval '2 days' end from generate_series(1,5)s(n) on conflict(id) do nothing;
select org_id,id,0,channel,case when status='clicked' then 'delivered' when status='opted_out' then 'cancelled' else status end,created_at,sent_at,delivered_at,case when status='failed' then 'Sample delivery failure' end from requests where org_id='d0000000-0000-4000-8000-000000000001' on conflict(request_id,step,channel) do nothing;
select 'demo-review-'||n,'d0000000-0000-4000-8000-000000000001','sample-'||n,author,rating,body,now()-make_interval(days=>n) from (values(1,'Alex R.',5,'Friendly team and a great haircut.'),(2,'Jordan K.',4,'Good service. A little wait on Saturday.'),(3,'Sam O.',2,'The appointment started late. Please improve scheduling.'))s(n,author,rating,body) on conflict(id) do nothing;
